#!/usr/bin/env python3
"""Writes DIRECTOR.md for level 3, lesson 10 (the anatomy of one winning trade on gold, in nine stages) from remotion/src/shots.json and
the picture / sound notes below. Made from the owner's script and voice; every cut and event is locked to the Whisper timings
(tools/director.py). «از آکادمی بکر تیک» is cut from the end of the voice and the subtitles.  usage: storyboard.py"""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__)); L = lambda *a: os.path.join(HERE, "..", *a)
d = json.load(open(L("remotion", "src", "shots.json"), encoding="utf-8")); V = json.load(open(L("timing", "variety.json"), encoding="utf-8"))
A = "auto: whoosh, tick/tap, pop on warnings, correct on ticks"
N = {  # id: picture and motion, sound
 "P01": ("«یک معامله سودده از آخر هفته شروع می‌شود…»؛ نوار هفت روز (شنبه تا جمعه، چپ به راست) با پلن، صبر، ورود، خروج؛ نوار طلایی «معامله» روی کل هفته؛ دکمه سبز «خرید» با «نه از این لحظه»", "riser + impact در شروع، " + A),
 "P02": ("نشان «سطح ۳ · درس ۱۰»؛ شش کاشی پلن ← آماده‌سازی ← ورود ← مدیریت ← خروج ← ژورنال روی کلمه‌هایشان؛ «همه درس‌های سطح ۲ و ۳، در یک معامله»", A),
 "P03": ("سپر طلایی «یک نمونه آموزشی»؛ «یاد گرفتن فرایند» ✓ در برابر «کپی کردن معامله» ✗", A),
 "P04": ("مرحله ۱ (شنبه): طرح هفتگی طلا؛ سقف‌ها و کف‌ها بالاتر (HH/HL)، شکست سقف قبلی و کمی برگشت", "riser + impact، " + A),
 "P05": ("طرح روزانه: نیمه ارزان سبز، اردر بلاک تازه طلایی، کف دو روز پیش با نقطه‌های بنفش نقدینگی", A),
 "P06": ("میز سبز: برگه پلن «اگر… آنگاه خرید»، هدف سقف هفته گذشته، سناریوی دوم «باطل»؛ تقویم هفته با خبر قرمز فقط جمعه", A),
 "P07": ("مرحله ۲: نوار هفته، دوشنبه و سه‌شنبه روشن: «آماده‌سازی ۱۰ دقیقه ✓» و «فقط نگاه»؛ «معامله: ۰»؛ «صبر، خودش یک قدم است»", A),
 "P08": ("مرحله ۳ (چهارشنبه): سه سشن؛ محدوده آسیا، لندن کف آسیا و کف دو روز پیش را می‌زند و وارد اردر بلاک روزانه می‌شود؛ کمی برگشت", A),
 "P09": ("میز سبز: ژورنال چهارشنبه صبح؛ پنج ردیف با تیک (روز آماده‌باش، نقدینگی، ناحیه، منتظر شکست، خبر ندارد)", A),
 "P10": ("مرحله ۴ (چارت XAUUSD M5): ۹:۵۰ نیویورک؛ حرکت قوی، شمع بالای سقف آخر، «شکست ساختار ↑»، شکاف قیمتی آبی؛ «عجله نکردیم»؛ برگشت به شکاف", "riser + impact، slide روی برش، " + A),
 "P11": ("مرحله ۵: پنل چک‌لیست ۷ ردیفی؛ ردیف جاری طلایی، تیک سبز روی هر «تیک» (۱ تا ۴)", "riser + impact، correct روی هر تیک"),
 "P12": ("ادامه چک‌لیست (۵ تا ۷)؛ کارت‌های حد ضرر، هدف و «حدود ۴ به ۱»؛ «۷ از ۷» و دکمه «ورود»", "correct روی تیک‌ها، ۷ از ۷ و ورود"),
 "P13": ("مرحله ۶: اول «حجم = ؟» بزرگ و قاب فرمول (تا تصویر ثابت نماند)، بعد «ریسک ۱٪»؛ حجم = ریسک به دلار ÷ فاصله حد ضرر (مثال فرضی ۱۰۰ ÷ ۸ = ۱۲٫۵ اونس)؛ «حجم دقیق» و «حد ضرر و هدف، همان لحظه»", A),
 "P14": ("مرحله ۷ (خطوط R): +۱R و سقف جدید، حد ضرر به نقطه ورود («بدون ریسک»)؛ ۱۱:۳۰ نزدیک بسته شدن لندن +۲R، «نصف بسته شد»؛ کارت معامله فقط با R", "slide روی برش، " + A),
 "P15": ("مرحله ۸ (پنج‌شنبه): هدف سقف هفته گذشته می‌خورد؛ کارت نیمه اول +۱R و نیمه دوم +۲R = حدود +۳R؛ «ریسک ۱٪ ← حدود ۳٪ سود»", "riser + impact، correct روی هدف"),
 "P16": ("مرحله ۹: میز سبز، ژورنال با عکس قبل و بعد؛ طبق پلن، ۷ از ۷، حس لحظه ورود، چه خوب بود، «می‌شد بهتر باشد: هیچ»", A),
 "P17": ("«حالا از بالا نگاه کن»: نوار کل معامله به ترتیب زمان؛ «ورود» فقط ۵٪ و سبز، بقیه ۹۵٪؛ «ورود، کوچک‌ترین قسمت معامله است»", "riser + impact، " + A),
 "P18": ("دو کارت: «هدف خورد +3R» و «اگر حد ضرر خورده بود −1R»، هر دو «طبق پلن = معامله خوب»؛ «نتیجه کیفیت را نشان نمی‌دهد، فرایند نشان می‌دهد»", A),
 "P19": ("تمرین: برگه «آخرین معامله من، در ۹ مرحله» با تیک و علامت سؤال روی مرحله‌های جاافتاده؛ «روی حساب آزمایشی یا کاغذی»", A),
 "P20": ("خلاصه: نه کاشی مرحله‌ها یکی‌یکی روی جمله روشن می‌شوند؛ «ورود، کوچک‌ترین قسمت آن است»", A),
 "P21": ("کانال یوتیوب؛ لایک «خوشحالمان کن»، دنبال کردن، زنگوله؛ اینستاگرام @kamalhaqjo و Follow", A),
 "P22": ("درس بعد: «کالبدشکافی یک معامله ضررده»؛ −1R؛ «ضرر خوب» ✓ و «ضرر بد» ✗", A),
 "P23": ("پایان برند: عکس کمال در دایره طلایی، Bakartech، «سطح ۳ · درس ۱۰»", "riser + impact بعد از «مالی»"),
}
fmt = lambda t: f"{int(t // 60)}:{t % 60:04.1f}"
md = ["# استوری‌بورد کارگردانی — سطح ۳، درس ۱۰: کالبدشکافی یک معامله سودده روی طلا (۹ مرحله) | Bakartech Academy", "",
      "> دستور ساخت برای Claude Code، شات‌به‌شات. صدا: `input/voice.mp3` · متن: `input/narration.txt` · 1920×1080 · 30fps · خروجی: `out/l3_lesson10_youtube.mp4`",
      "> از روی متن درس و فایل صدایی که مالک فرستاد؛ زمان هر شات و هر رویداد با Whisper به جمله‌ی گوینده قفل است (`tools/director.py`). «از آکادمی بکر تیک» از آخر صدا و زیرنویس حذف شده و جمله روی «مالی» تمام می‌شود.", "",
      "## ۰. قانون‌های کارگردانی", "",
      "1. دو شات چارت (P10 نیویورک M5 و P14 مدیریت با R، حدود ۱۳٪ زمان)؛ بقیه موشن‌گرافیک. چارت پلتفرم بی‌نام با نماد XAUUSD (طلا) و برچسب «مثال فرضی»؛ طرح‌ها هم برچسب «مثال فرضی» دارند.",
      "2. نوار ۹ مرحله بالای صفحه (پلن، صبر، آماده‌سازی، نیویورک، چک‌لیست، حجم، مدیریت، خروج، ژورنال) از P04 تا P16؛ هر شات مرحله‌اش را با سرتیتر «مرحله N» نشان می‌دهد. اردر بلاک طلایی، نقدینگی بنفش، شکاف قیمتی آبی، نیمه ارزان سبز؛ خطوط R: ورود سفید خط‌چین، حد ضرر قرمز، سربه‌سر طلایی، هدف سبز.",
      "3. در همه‌ی طرح‌ها و چارت‌ها زمان از چپ به راست می‌رود (مثل هر چارت قیمت)، حتی روزهای هفته و نوار کل معامله.",
      "4. دو شات پشت سر هم از یک نوع نباشند (`director.py` چک می‌کند)؛ هر ۴ تا ۷ ثانیه تغییر بصری؛ زمان هر شات و رویداد با Whisper به جمله‌ی گوینده قفل است.",
      "5. Vazirmatn برای فارسی، Inter برای اعداد و نمادها. متن روی صفحه کوتاه، داخل کارت شیشه‌ای. مدیریت و نتیجه فقط با R (بدون دلار)، چون مبلغ حساب فرضی است.",
      "6. صدا: موزیک آرام Bakartech با ducking زیر گوینده؛ افکت‌ها از پک Davino.creator (`reels/brand/sfx`)، حداکثر یک impact در ۱۵ ثانیه، فقط روی برش‌ها یا بعد از کلمه.",
      "7. برند: لوگوی KH بالا سمت چپ با نشان «سطح ۳» کنارش، «Bakartech» کوچک پایین سمت چپ، پایان با عکس کمال داخل دایره‌ی طلایی و نشان «سطح ۳».",
      "8. خروجی با رنگ استاندارد (yuv420p، BT.709، محدوده‌ی TV) تا همان فایل در یوتیوب و اینستاگرام آپلود شود (`tools/finish.sh`).",
      "9. کنترل کیفیت: اول contact sheet از همه‌ی شات‌ها، بعد رندر کامل، بعد freezedetect، blackdetect، LUFS و شنیدن پایان صدا (ASR).", "",
      "## ۱. شات‌لیست", "", "| # | زمان | جمله گوینده | نوع صحنه | تصویر و حرکت | متن روی صفحه | SFX |", "|---|---|---|---|---|---|---|"]
for i, s in enumerate(d["shots"], 1):
    pic, sfx = N[s["id"]]
    md.append(f"| {i} | {fmt(s['from'])}–{fmt(s['to'])} | {s['spoken']} | {V['types'][s['type']]} | {pic} (دوربین: {s['cam']}) | {' / '.join(s['text']) or '—'} | {sfx} |")
tot = sum(V["seconds"].values())
md += ["", "**آمار تنوع:** " + " · ".join(f"{V['types'][k]} {n}" for k, n in sorted(V["count"].items(), key=lambda x: -x[1])) +
       f" · زمان چارت {V['seconds'].get('chart', 0):.0f} ثانیه از {tot:.0f} ({100 * V['seconds'].get('chart', 0) / tot:.0f}٪). هیچ دو شات پشت سر همی هم‌نوع نیستند.", "",
       "## ۲. کامپوننت‌ها", "",
       "**از درس‌های قبل:** Headline، Chip، ChannelButtons، BrandOutro، `StepProgress` (نوار ۹ مرحله)، `NumHead`؛ از سطح ۲: `Platform`، `StructChart`، `Ico`؛ از سطح ۲ و ۳: `OBBox`، `FVGBox`، `Liq`، `PDBox`، `Sess`، `Lv`، `Sketch`، `Hypo`، `Big`، `OkMark`.",
       "**جدید در این درس (`remotion/src/scenes.jsx`، انتهای فایل):**",
       "- `Week` (نوار هفت روز، چپ به راست)، `StageHead` (سرتیتر «مرحله N»)، شمع‌های دستی M5 با شکست ساختار و شکاف قیمتی.",
       "- `hookWeek`، `agenda10`، `disclaim`، `weekly10`، `daily10`، `plan10`، `wait10`، `wedPrep`، `wedJournal`، `nyBOS`، `check10`، `size10`، `manage10`، `exit10`، `journal10`، `bigPicture`، `processNote`، `practice10`، `summary9`، `nextLoss`، `outro10`.", "",
       "## ۳. خروجی‌ها", "", "- `out/l3_lesson10_youtube.mp4` (1920×1080، برای یوتیوب و اینستاگرام)", "- `out/l3_lesson10_instagram_part1..3_1920x1080.mp4` (اگر اینستاگرام ویدیوی بلند را نپذیرفت، سه بخش زیر سه دقیقه)",
       "- `out/subtitles.srt` و `out/subtitles.vtt`", "- `remotion/out/contact_sheet.png`", "- `remotion/out/timing.json`", ""]
open(L("DIRECTOR.md"), "w", encoding="utf-8").write("\n".join(md))
print("DIRECTOR.md", len(d["shots"]), "shots")
